#include <assert.h>
#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define DATE_SIZE 11
#define CATEGORY_SIZE 41
#define LINE_SIZE 128

struct Expense {
    char date[DATE_SIZE];
    char category[CATEGORY_SIZE];
    long long cents;
};

static int leap_year(int year) {
    return year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
}

static int valid_date(const char *date) {
    static const int days[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    int year = 0;
    int month = 0;
    int day = 0;
    int i;
    if (date == NULL || strlen(date) != 10U || date[4] != '-' || date[7] != '-') return 0;
    for (i = 0; i < 10; ++i) {
        if (i != 4 && i != 7 && !isdigit((unsigned char)date[i])) return 0;
    }
    for (i = 0; i < 4; ++i) year = year * 10 + (date[i] - '0');
    month = (date[5] - '0') * 10 + (date[6] - '0');
    day = (date[8] - '0') * 10 + (date[9] - '0');
    if (year < 1 || month < 1 || month > 12 || day < 1) return 0;
    if (month == 2 && leap_year(year)) return day <= 29;
    return day <= days[month - 1];
}

static int valid_category(const char *category) {
    size_t i;
    size_t length;
    if (category == NULL) return 0;
    length = strlen(category);
    if (length == 0U || length >= CATEGORY_SIZE) return 0;
    for (i = 0; i < length; ++i) {
        unsigned char ch = (unsigned char)category[i];
        if (ch < 32U || ch == 127U || ch == (unsigned char)'|') return 0;
    }
    return 1;
}

static int parse_record(char *line, struct Expense *expense) {
    char *first;
    char *second;
    char *end;
    long long cents;
    size_t date_length;
    size_t category_length;
    size_t line_length;
    if (line == NULL || expense == NULL) return 0;
    line_length = strlen(line);
    while (line_length > 0U && (line[line_length - 1U] == '\n' || line[line_length - 1U] == '\r')) {
        line[--line_length] = '\0';
    }
    first = strchr(line, '|');
    if (first == NULL) return 0;
    *first = '\0';
    second = strchr(first + 1, '|');
    if (second == NULL || strchr(second + 1, '|') != NULL) return 0;
    *second = '\0';
    if (!valid_date(line) || !valid_category(first + 1)) return 0;
    if (second[1] == '\0') return 0;
    errno = 0;
    cents = strtoll(second + 1, &end, 10);
    if (errno == ERANGE || end == second + 1 || *end != '\0' || cents <= 0) return 0;
    date_length = strlen(line);
    category_length = strlen(first + 1);
    if (date_length >= DATE_SIZE || category_length >= CATEGORY_SIZE) return 0;
    memcpy(expense->date, line, date_length + 1U);
    memcpy(expense->category, first + 1, category_length + 1U);
    expense->cents = cents;
    return 1;
}

static int add_total(long long *total, long long cents) {
    if (total == NULL || cents < 0 || *total > LLONG_MAX - cents) {
        return 0;
    }
    *total += cents;
    return 1;
}

int main(void) {
    char line[LINE_SIZE];
    struct Expense expense;
    long long total = 0;
    char valid[] = "2024-02-29|Groceries|1250";
    char bad_date[] = "2023-02-29|Groceries|1250";
    char bad_amount[] = "2024-03-01|Fuel|12x";
    char bad_delimiter[] = "2024-03-01|Fuel|1200|extra";
    char bad_category[] = "2024-03-01|Fuel|March|1200";
    char zero_amount[] = "2024-03-01|Fuel|0";

    assert(valid_date("2000-02-29"));
    assert(valid_date("2024-02-29"));
    assert(!valid_date("1900-02-29"));
    assert(!valid_date("2023-02-29"));
    assert(!valid_date("2024-13-01"));
    assert(!valid_date("2024-04-31"));
    assert(parse_record(valid, &expense));
    assert(strcmp(expense.date, "2024-02-29") == 0);
    assert(strcmp(expense.category, "Groceries") == 0 && expense.cents == 1250);
    assert(!parse_record(bad_date, &expense));
    assert(!parse_record(bad_amount, &expense));
    assert(!parse_record(bad_delimiter, &expense));
    assert(!parse_record(bad_category, &expense));
    assert(!parse_record(zero_amount, &expense));
    assert(add_total(&total, 1250));
    assert(add_total(&total, 250));
    assert(total == 1500);
    assert(!add_total(&total, LLONG_MAX));
    assert(!parse_record(NULL, &expense));
    (void)snprintf(line, sizeof line, "2026-11-17|Transport|990");
    assert(parse_record(line, &expense) && expense.cents == 990);
    puts("Expense record parsing and total tests passed.");
    return 0;
}

#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define DATE_SIZE 11
#define CATEGORY_SIZE 41
#define LINE_SIZE 128
#define RECORD_LINE_SIZE 128
#define FILE_NAME "expenses.txt"

struct Expense {
    char date[DATE_SIZE];
    char category[CATEGORY_SIZE];
    long long cents;
};

enum ReadResult { READ_OK, READ_END, READ_INVALID };

static int leap_year(int year) {
    return year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
}

static int valid_date(const char *date) {
    static const int days[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    int year = 0, month, day, i;
    if (date == NULL || strlen(date) != 10U || date[4] != '-' || date[7] != '-') return 0;
    for (i = 0; i < 10; ++i)
        if (i != 4 && i != 7 && !isdigit((unsigned char)date[i])) return 0;
    for (i = 0; i < 4; ++i) year = year * 10 + date[i] - '0';
    month = (date[5] - '0') * 10 + date[6] - '0';
    day = (date[8] - '0') * 10 + date[9] - '0';
    if (year < 1 || month < 1 || month > 12 || day < 1) return 0;
    if (month == 2 && leap_year(year)) return day <= 29;
    return day <= days[month - 1];
}

static int valid_category(const char *category) {
    size_t i, length;
    if (category == NULL) return 0;
    length = strlen(category);
    if (length == 0U || length >= CATEGORY_SIZE) return 0;
    for (i = 0; i < length; ++i) {
        unsigned char ch = (unsigned char)category[i];
        if (ch < 32U || ch == 127U || ch == (unsigned char)'|') return 0;
    }
    return 1;
}

static char *trim(char *text) {
    char *start = text, *end;
    while (isspace((unsigned char)*start)) ++start;
    end = start + strlen(start);
    while (end > start && isspace((unsigned char)end[-1])) --end;
    *end = '\0';
    return start;
}

static enum ReadResult read_line(const char *prompt, char *buffer, size_t size) {
    size_t length;
    int ch;
    fputs(prompt, stdout);
    if (fgets(buffer, (int)size, stdin) == NULL) return READ_END;
    length = strlen(buffer);
    if (length > 0U && buffer[length - 1U] == '\n') {
        buffer[length - 1U] = '\0';
        return READ_OK;
    }
    ch = getchar();
    if (ch == '\n' || ch == EOF) return READ_OK;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return READ_INVALID;
}

static int read_positive_id_or_menu(const char *prompt, int *choice) {
    char line[LINE_SIZE], *start, *end;
    long value;
    enum ReadResult result = read_line(prompt, line, sizeof line);
    if (result != READ_OK) return result == READ_END ? 0 : -1;
    start = trim(line);
    errno = 0;
    value = strtol(start, &end, 10);
    while (isspace((unsigned char)*end)) ++end;
    if (start == end || *end != '\0' || errno == ERANGE
        || value < 0L || value > (long)INT_MAX) return -1;
    *choice = (int)value;
    return 1;
}

static int read_amount(const char *prompt, long long *cents) {
    char line[LINE_SIZE], *start, *p;
    unsigned long long whole = 0ULL;
    unsigned int fraction = 0U;
    int digits = 0, decimals = 0;
    enum ReadResult result = read_line(prompt, line, sizeof line);
    if (result != READ_OK) return result == READ_END ? 0 : -1;
    start = trim(line);
    p = start;
    while (*p >= '0' && *p <= '9') {
        unsigned int digit = (unsigned int)(*p - '0');
        if (whole > ((unsigned long long)LLONG_MAX / 100ULL - digit) / 10ULL) return -1;
        whole = whole * 10ULL + digit;
        ++digits;
        ++p;
    }
    if (*p == '.') {
        ++p;
        while (*p >= '0' && *p <= '9' && decimals < 2) {
            fraction = fraction * 10U + (unsigned int)(*p - '0');
            ++decimals;
            ++p;
        }
        if (decimals == 0) return -1;
    }
    if (*p != '\0' || digits == 0) return -1;
    if (decimals == 1) fraction *= 10U;
    if (whole > (unsigned long long)LLONG_MAX / 100ULL) return -1;
    if (whole * 100ULL > (unsigned long long)LLONG_MAX - fraction) return -1;
    *cents = (long long)(whole * 100ULL + fraction);
    if (*cents <= 0) return -1;
    return 1;
}

static int read_expense_date(char date[DATE_SIZE]) {
    char line[LINE_SIZE], *clean;
    enum ReadResult result = read_line("Date (YYYY-MM-DD): ", line, sizeof line);
    size_t length;
    if (result != READ_OK) return result == READ_END ? 0 : -1;
    clean = trim(line);
    length = strlen(clean);
    if (length != 10U || !valid_date(clean)) return -1;
    memcpy(date, clean, DATE_SIZE);
    return 1;
}

static int read_category(char category[CATEGORY_SIZE]) {
    char line[LINE_SIZE], *clean;
    enum ReadResult result = read_line("Category (no | character): ", line, sizeof line);
    size_t length;
    if (result != READ_OK) return result == READ_END ? 0 : -1;
    clean = trim(line);
    length = strlen(clean);
    if (length >= CATEGORY_SIZE || !valid_category(clean)) return -1;
    memcpy(category, clean, length + 1U);
    return 1;
}

static int parse_record(char *line, struct Expense *expense) {
    char *first, *second, *end;
    long long cents;
    size_t length;
    if (line == NULL || expense == NULL) return 0;
    length = strlen(line);
    while (length > 0U && (line[length - 1U] == '\n' || line[length - 1U] == '\r'))
        line[--length] = '\0';
    first = strchr(line, '|');
    if (first == NULL) return 0;
    *first = '\0';
    second = strchr(first + 1, '|');
    if (second == NULL || strchr(second + 1, '|') != NULL) return 0;
    *second = '\0';
    if (!valid_date(line) || !valid_category(first + 1) || second[1] == '\0') return 0;
    errno = 0;
    cents = strtoll(second + 1, &end, 10);
    if (errno == ERANGE || end == second + 1 || *end != '\0' || cents <= 0) return 0;
    memcpy(expense->date, line, strlen(line) + 1U);
    memcpy(expense->category, first + 1, strlen(first + 1) + 1U);
    expense->cents = cents;
    return 1;
}

static int append_expense(const struct Expense *expense) {
    FILE *file = fopen(FILE_NAME, "a");
    int ok;
    if (file == NULL) {
        perror("Could not open expense file for appending");
        return 0;
    }
    ok = fprintf(file, "%s|%s|%lld\n", expense->date,
                 expense->category, expense->cents) >= 0;
    if (fclose(file) == EOF) {
        ok = 0;
    }
    return ok;
}

static void add_expense(void) {
    struct Expense expense;
    int status;
    long long cents;
    status = read_expense_date(expense.date);
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid date."); return; }
    status = read_category(expense.category);
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid category."); return; }
    status = read_amount("Amount (for example 125.50): ", &cents);
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid amount; use up to two decimal places."); return; }
    expense.cents = cents;
    if (append_expense(&expense)) puts("Expense saved.");
    else puts("Expense could not be saved.");
}

static void show_expenses(void) {
    FILE *file = fopen(FILE_NAME, "r");
    char line[RECORD_LINE_SIZE];
    size_t valid_count = 0U, invalid_count = 0U;
    long long total = 0;
    int total_overflow = 0;
    if (file == NULL) {
        if (errno == ENOENT) { puts("No expense file yet."); return; }
        perror("Could not open expense file");
        return;
    }
    puts("\nDATE       CATEGORY                                 AMOUNT");
    while (fgets(line, sizeof line, file) != NULL) {
        struct Expense expense;
        size_t length = strlen(line);
        if (length > 0U && line[length - 1U] != '\n' && !feof(file)) {
            int ch;
            while ((ch = fgetc(file)) != '\n' && ch != EOF) { }
            ++invalid_count;
            continue;
        }
        if (!parse_record(line, &expense)) {
            ++invalid_count;
            continue;
        }
        printf("%s %-40s %lld.%02lld\n", expense.date, expense.category,
               expense.cents / 100LL, expense.cents % 100LL);
        ++valid_count;
        if (!total_overflow && total > LLONG_MAX - expense.cents) total_overflow = 1;
        else if (!total_overflow) total += expense.cents;
    }
    if (ferror(file)) perror("Error while reading expense file");
    if (fclose(file) == EOF) perror("Error while closing expense file");
    printf("Valid records: %zu | Invalid lines skipped: %zu\n", valid_count, invalid_count);
    if (total_overflow) puts("Total is too large to represent.");
    else printf("Total: %lld.%02lld\n", total / 100LL, total % 100LL);
}

int main(void) {
    for (;;) {
        int choice;
        int status;
        puts("\nEXPENSE TRACKER");
        puts("1 Add expense  2 List expenses and total  0 Exit");
        status = read_positive_id_or_menu("Choose: ", &choice);
        if (status == 0) { puts("\nEnd of input. Goodbye."); break; }
        if (status < 0 || (choice != 0 && choice != 1 && choice != 2)) {
            puts("Enter 0, 1 or 2.");
            continue;
        }
        if (choice == 0) { puts("Goodbye."); break; }
        if (choice == 1) add_expense();
        else show_expenses();
    }
    return 0;
}
